 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(v == k for row in grid for v in row) for k in range(10)]
    background = max(range(10), key=lambda k: counts[k])

    # Separator rows/columns contain only wall/junction colors, not room fill.
    ys = [r for r in range(h) if background not in grid[r]]
    xs = [c for c in range(w) if all(grid[r][c] != background for r in range(h))]
    if len(ys) < 2 or len(xs) < 2:
        return []

    crossings = {(r, c) for r in ys for c in xs}
    wall_counts = [0] * 10
    for r in ys:
        for c in range(w):
            if (r, c) not in crossings:
                wall_counts[grid[r][c]] += 1
    for c in xs:
        for r in range(h):
            if (r, c) not in crossings:
                wall_counts[grid[r][c]] += 1
    wall = max(range(10), key=lambda k: wall_counts[k])

    marked = [(i, j) for i, r in enumerate(ys) for j, c in enumerate(xs)
              if grid[r][c] != wall]
    if not marked:
        return []
    r0, r1 = min(i for i, _ in marked), max(i for i, _ in marked)
    c0, c1 = min(j for _, j in marked), max(j for _, j in marked)

    decoded = []
    for i in range(r0, r1):
        outrow = []
        for j in range(c0, c1):
            a = grid[ys[i]][xs[j]]
            b = grid[ys[i]][xs[j + 1]]
            c = grid[ys[i + 1]][xs[j]]
            d = grid[ys[i + 1]][xs[j + 1]]
            outrow.append(a if a == b == c == d and a != wall else background)
        decoded.append(outrow)
    return decoded
"
